package com.lyrashop.user.service;
import java.math.BigDecimal;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.lyrashop.order.repository.ShopOrderRepository;import com.lyrashop.user.entity.*;import com.lyrashop.user.repository.*;
@Service public class LoyaltyService{private final LoyaltyAccountRepository accounts;private final LoyaltyTransactionRepository tx;private final ShopOrderRepository orders;
 public LoyaltyService(LoyaltyAccountRepository a,LoyaltyTransactionRepository t,ShopOrderRepository o){accounts=a;tx=t;orders=o;}
 @Transactional public Map<String,Object> get(UUID u){var a=accounts.findById(u).orElseGet(()->accounts.save(LoyaltyAccount.create(u)));return response(u,a);}
 @Transactional public Map<String,Object> checkIn(UUID u){var a=accounts.findById(u).orElseGet(()->LoyaltyAccount.create(u));try{a.checkIn(LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")));}catch(IllegalStateException e){return response(u,a);}accounts.save(a);tx.save(LoyaltyTransaction.checkIn(u));return response(u,a);}
 public List<Map<String,Object>> history(UUID u){return tx.findAllByUserIdOrderByCreatedAtDesc(u).stream().map(t->Map.<String,Object>of("amount",t.getAmount(),"type",t.getType(),"description",t.getDescription(),"createdAt",t.getCreatedAt())).toList();}
 private Map<String,Object> response(UUID u,LoyaltyAccount a){BigDecimal spend=orders.sumPaidTotalByUserId(u);String tier=spend.compareTo(new BigDecimal("5000000"))>=0?"DIAMOND":spend.compareTo(new BigDecimal("2000000"))>=0?"GOLD":"MEMBER";return Map.of("tier",tier,"coinBalance",a.getCoinBalance(),"totalSpend",spend,"checkedInToday",LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh")).equals(a.getLastCheckIn()),"nextTierSpend",tier.equals("DIAMOND")?BigDecimal.ZERO:new BigDecimal(tier.equals("GOLD")?"5000000":"2000000"));}}
